build:structure_diff.api:
structure.py (importable; CLI `python tools/structure.py [floors] [--no-png] [--no-doc] [--zoom x0 y0 x1 y1]`; default = all floors):
  analyze_floor(n|Floor) -> dict, the same content as output/structure/F0x.json. Keys:
    floor, level, grid, elements, tr_block, shafts, stairs, lifts, dash, dims, annotations, openings_on_structure, summary.
    elements[]: {id 'C01'/'SW06'/'CORE01'/'CX01', kind column|shear_wall|core|column_xbox, sources, only_in_tr_block, hatch_only, bbox, centroid, size, size_txt, area, perimeter, covered_by_walls, covered_by_concrete_or_shaft, exposed_perimeter, outline_on_W, w_inside_len, grid_ref, spans_axes{x,y}, faces[], outline, notes, wall_thickness (core)}
    grid: {x_axes[{label, coord, source, tag_offsets}], y_axes[...], x_spacings_east_to_west, y_spacings_south_to_north, bubbles, displaced_tags, other_lines, notes}
    shafts[]: {id SHnn, kind, bbox, size_txt, area, perimeter, dash_diagonals, hatched, grid_ref, floors}
    stairs[]: {id ST1/ST2, bbox, flights_ST, flights_DASH_above_cut, eye, blank_level_tags}
    lifts: {cars, door_lines_MASS, core_size, core_wall_thickness, HAT_hatches_in_shafts}
    dash: {lines[{a, b, len, class, ref}], summary}
    dims: {dims[{id, handle, text, value, actual, p2, p3, dimline, direction, snap_p2, snap_p3, class, grid_ref}], by_class, histogram, wall_thickness_values, axis_chain_check, old_grid_offset}
    annotations: {titles, blank level tags, level marks, area_schedule_sidewalk, MASS (plot_boundary), FUR, LP, PR1}
  read_grid(fl), grid_ref(grid, x, y) -> 'د+2.25 / 8+1.58', grid_between(grid, x0, x1, y0, y1)
  sheet_inserts(fl, layers), FloorData(fl)
  run(floors=None, png=True, doc=True) -> list of results. Writes the JSON and PNGs, harmonizes SH ids, and refreshes the AUTO tables in the findings doc.
  harmonize_shaft_ids(allres), doc_tables(allres), update_doc(blocks), render(res, png, mode='structure'|'dims', zoom=(x0, y0, x1, y1))
floor_compare.py (CLI `python tools/floor_compare.py [--ref F05] [--no-png] [--no-doc]`):
  compare_floors(ref=None) -> {reference, floors, matrix[layer][A][B] (m of A not in B), blocks_matrix, door_blocks_matrix, texts_matrix, dims_matrix, struct_matrix, total_matrix, identical_groups, per_floor_vs_ref, regions[{id, bbox, center, rooms_near, floors_differing_from_ref, floors_unlike_ref, variants, changes}]}
  equal_groups(matrix, labels), cmp_table(res), write_doc(res), extract(fl)
